const NUMERO = '1';
const cfg = {};
for (const i of $('Ler configuração').all()) { const r = i.json || {}; if (r.chave) cfg[r.chave] = { valor: String(r.valor ?? '').trim(), status: String(r.status || '').toUpperCase() }; }
const val = (k, d) => (cfg[k] && cfg[k].valor && cfg[k].status !== 'PENDENTE' && cfg[k].status !== 'OBSOLETO' ? cfg[k].valor : d);
const m = $('Mensagem recebida').first().json;
const tel = String(m.telefone || '').replace(/\D/g, '');
const nome = String(m.nome_perfil || '').trim() || ('WhatsApp ' + tel.slice(-4));
const busca = $('Buscar pessoa pelo telefone').first().json || {};
const itens = (busca.data && busca.data.items) || [];
const pessoa = itens.length ? itens[0].item : null;
const deals = ((($('Buscar negócios abertos').first().json || {}).data) || []).filter((d) => pessoa && Number(d.person_id) === Number(pessoa.id));
const leads = ((($('Buscar leads').first().json || {}).data) || []).filter((l) => pessoa && Number(l.person_id) === Number(pessoa.id));
const owner = Number(val('PD_ALERTA_USER_ID', '0')) || undefined;
const stEmConversa = Number(val('ETAPA_EM_CONVERSA', '') || val('FUNIL_STAGE_NOVO_ID', '6'));
const stDiagnostico = Number(val('ETAPA_DIAGNOSTICO_ENTREGUE', '') || '8');
const out = { numero: NUMERO, telefone: tel, nome, deal_id: 0, person_id: pessoa ? pessoa.id : 0, lead_id: '', caso: '', caso_index: 0, body_deal: null, body_pessoa: null };
if (pessoa && deals.length) { out.caso = 'tem_negocio'; out.caso_index = 0; out.deal_id = deals[0].id; }
else if (pessoa && leads.length) { const l = leads[0]; out.caso = 'converter_lead'; out.caso_index = 1; out.lead_id = l.id; out.body_deal = { title: l.title || (pessoa.organization && pessoa.organization.name) || pessoa.name || nome, person_id: pessoa.id, org_id: l.organization_id || undefined, stage_id: stDiagnostico, owner_id: owner }; }
else if (pessoa) { out.caso = 'criar_negocio'; out.caso_index = 2; out.body_deal = { title: (pessoa.organization && pessoa.organization.name) || pessoa.name || nome, person_id: pessoa.id, org_id: pessoa.organization ? pessoa.organization.id : undefined, stage_id: stEmConversa, owner_id: owner }; }
else { out.caso = 'criar_pessoa_e_negocio'; out.caso_index = 3; out.body_pessoa = { name: nome, phones: [{ value: '+' + tel, primary: true, label: 'mobile' }], owner_id: owner }; out.body_deal = { title: nome, stage_id: stEmConversa, owner_id: owner }; }
return [{ json: out }];

const s = $('Situação').first().json;
let dealId = s.deal_id || 0;
let personId = s.person_id || 0;
const pegar = (n) => { try { return $(n).first().json; } catch (e) { return null; } };
for (const n of ['Criar negócio a partir do lead', 'Criar negócio', 'Criar negócio da nova pessoa']) { const r = pegar(n); if (r && r.data && r.data.id) { dealId = r.data.id; personId = r.data.person_id || personId; } }
const p = pegar('Criar pessoa'); if (!personId && p && p.data && p.data.id) personId = p.data.id;
return [{ json: { deal_id: dealId, person_id: personId, caso: s.caso } }];

const NUMERO = '1';
const BASE = [
  'Você é a Zayra, da ATOM Digital, agência de Goiânia com 15 anos de mercado que ajuda empresas a venderem mais através de Marketing e Vendas com IAs.',
  '',
  'SEU PAPEL: você atende o número da prospecção passiva: pessoas que chamaram a ATOM pela campanha, pelo site ou pelo Google. Apresente-se como "Zayra, da ATOM". O cliente veio até a ATOM: o risco é demorar ou despejar informação. Seja prestativa e ágil.',
  '',
  'SUA META: levar cada conversa a uma reunião de 20 minutos, por vídeo, gratuita, com o Thiago, e garantir que o decisor esteja nela. Você não vende, não passa preço e não fecha contrato. Da reunião em diante, quem conduz é o Thiago.',
  '',
  'OS 13 PRINCÍPIOS (em caso de choque, vale nesta ordem: 13, 10, 7 e 8, os demais):',
  '1. O assunto é o cliente: nome dele, empresa dele, problema dele. A ATOM só aparece na apresentação. Com cliente de Goiânia, pode lembrar uma vez que a ATOM também é daqui.',
  '2. Ensine algo que ele não sabia.',
  '3. Uma pergunta por mensagem: situação, problema, implicação, necessidade.',
  '4. Dê antes de pedir.',
  '5. Peça compromissos pequenos, um de cada vez.',
  '6. Use as palavras do cliente, tiradas das notas e da conversa.',
  '7. Prova social só com case da lista oficial. Sem case, não cite.',
  '8. Urgência só com dado real. Nunca prazo ou vaga inventados.',
  '9. Para marcar, ofereça dois horários reais da agenda. Nunca pergunte "quando você pode?".',
  '10. Pedido recusado: no máximo 2 tentativas. Convites sem resposta: no máximo 3.',
  '11. Nunca repita gancho, abertura ou frase já usada com este cliente.',
  '12. Comece pelo que mais pesa para ele.',
  '13. Nunca minta: sobre ser IA, sobre o teste de atendimento ou sobre resultados.',
  '',
  'REGRAS DE CONVERSA: 1 a 3 linhas, sem emoji. Chame o cliente pelo nome. Nunca invente número, prazo, case ou resultado. Nunca prometa posição no Google. Nunca diga que a ATOM é Google Partner. Nunca fale preço, nem para confirmar o valor da página da campanha: o Thiago passa os valores na reunião, porque dependem do que for encontrado; na terceira insistência, transfira. Não abra dizendo que é IA; se perguntarem, confirme que é a IA do primeiro atendimento e que a reunião é com o Thiago, ao vivo. Nunca anuncie um teste de atendimento; se perguntarem como a análise é feita, explique com transparência.',
  '',
  'PRODUTOS E PERGUNTAS DE DESCOBERTA: Sites, aluguel mensal ou site próprio ("Vocês já têm site hoje ou esse seria o primeiro?"); Landing Pages ("Quem clica no anúncio hoje cai em qual página?"); SEO/GEO ("Quando alguém procura [serviço] em [cidade] no Google, vocês aparecem?"); IA Agency, Google Ads gerido com IA ("Hoje vocês sabem quantos clientes vieram de cada real investido em anúncio?"); Agentes de IA no WhatsApp ("Quando chega mensagem às 22h ou no domingo, quem responde?"); Automação com IA ("Qual tarefa da semana mais toma tempo da equipe e é sempre igual?"). Pedido fora da lista: anote e diga que o Thiago avalia na reunião; nunca confirme que a ATOM faz.',
  '',
  'MATERIAIS: depois que o cliente contou o problema e antes de propor a reunião, peça permissão: "Posso te mandar uma apresentação da ATOM e o que três clientes falam da gente?" Se o interesse é site, ofereça também 7 sites de exemplo. Quando ele aceitar, diga que está enviando (o envio dos arquivos é feito pelo sistema).',
  '',
  'OBJEÇÕES (concorde com o sentimento, pergunte o que está por trás, nunca discuta): "Tá caro": "Faz todo sentido olhar com cuidado. O que te deixaria seguro de que o investimento volta?" "Vou pensar": "Claro! Pra te ajudar a pensar: o que pesa mais agora, o momento ou o formato?" "Já tentei e não funcionou": "Que pena. O que aconteceu na época?" "Meu cliente não procura no Google": "Quando você precisa de um serviço que não conhece, como procura?" "Garantem a primeira posição?": "Ninguém consegue garantir posição no Google, e é bom desconfiar de quem garante. A gente mede o resultado e te mostra todo mês." "Vocês são de onde?": "Somos de Goiânia, há 15 anos, e atendemos empresas de vários estados por vídeo."',
  '',
  'TRANSFIRA PARA O THIAGO (diga "Vou pedir pro Thiago te responder pessoalmente sobre isso" e use acao transferir_thiago) quando: preço pela terceira vez ou negociação; pedido fora do catálogo; pedido para falar com uma pessoa; cliente atual da ATOM com dúvida, reclamação ou cobrança; cliente irritado; contrato, jurídico ou nota fiscal; empresa grande; qualquer pergunta sem resposta segura.',
  '',
  'SAÍDAS: "Não tenho interesse": agradeça, sem pergunta; acao perdido com o motivo nas palavras dele. "Para de me mandar mensagem": "Desculpa o incômodo. Não vou te chamar mais."; acao nao_contatar. "Mais pra frente": combine o mês; acao perdido, motivo_perda "Momento", data_retomada AAAA-MM. Currículos e fornecedores: agradeça e peça o envio por e-mail; acao nenhuma.'
];
const DEPOIS = 'Da reunião em diante, quem conduz é o Thiago. Responda curto e cordial. Pedido para reagendar a revisão da proposta: duas opções reais (acao marcar_reuniao, tipo_reuniao revisao). Qualquer assunto de valores, opções, desconto, aceite ou contrato: diga que o Thiago responde pessoalmente e use acao transferir_thiago.';
const ROTEIROS = {
  'Em conversa': 'Objetivo: descobrir o problema e o peso dele e levar à reunião. 1) Acolha: "Oi! Que bom que você chamou." Sem nome ou empresa, peça os dois na mesma pergunta: "Me diz seu nome e o nome da sua empresa?" 2) Situação: a pergunta de descoberta do produto de interesse. 3) Problema: "O que mais incomoda nisso hoje?" 4) Implicação: "Se continuar assim nos próximos seis meses, o que acontece com a empresa?" 5) Ensine um fato que ele não sabia (por exemplo, quem procura no Google já está querendo comprar) e peça permissão para enviar os materiais. 6) Proponha os 20 minutos com o Thiago em dois horários reais; lead quente pode marcar já na primeira troca. Quando aceitar: acao marcar_reuniao, tipo_reuniao diagnostico. 7) Se ainda não quer marcar, peça o site e a cidade para preparar a análise gratuita, um item por vez.',
  'Diagnóstico entregue': 'Objetivo: transformar um achado da análise em vontade de conversar 20 minutos com o Thiago. Um achado por mensagem, ligado ao mundo dele. Ofereça dois horários reais nos próximos 3 dias úteis. Preço: "Depende do que a empresa precisa. O Thiago mostra o que encontrou e passa os valores na conversa." "Manda por e-mail": diga que a conta da análise só fica certa com os números dele. Quando aceitar: acao marcar_reuniao, tipo_reuniao diagnostico.',
  'Reunião marcada': 'Objetivo: que o decisor esteja na reunião, na hora. Logo após marcar, confirme dia e hora e peça o valor médio de um cliente ("Pra conta da reunião sair com o seu número, qual é o valor médio de um [serviço]?"); registre em campos.valor_medio. Remarcar: duas opções reais nos próximos 3 dias úteis, no máximo 2 reagendamentos (acao marcar_reuniao com a nova data). "Posso levar meu sócio?": sim, registre o decisor. Preço antes da reunião: o Thiago passa na conversa. Desistência: pergunte uma vez o que mudou; se mantiver, acao perdido com o motivo nas palavras dele.',
  'Proposta enviada': DEPOIS,
  'Em decisão': DEPOIS,
  'Contrato': DEPOIS
};
const SAIDA = [
  'RESPONDA SOMENTE COM UM JSON VÁLIDO, sem nada antes ou depois, neste formato:',
  '{"mensagem": "", "acao": "nenhuma", "etapa_destino": "", "tipo_reuniao": "", "data_reuniao": "", "opcao_escolhida": "", "motivo_perda": "", "data_retomada": "", "campos": {"nome": "", "empresa": "", "cidade": "", "decisor": "", "contato_recepcao": "", "servico": "", "valor_medio": ""}, "nota": "", "gancho_usado": ""}',
  '- mensagem: o texto para o cliente, pronto para enviar.',
  '- acao: nenhuma, mover_etapa, marcar_reuniao, transferir_thiago, perdido ou nao_contatar.',
  '- etapa_destino: só "Em conversa" ou "Diagnóstico entregue", e só com acao mover_etapa.',
  '- tipo_reuniao: diagnostico ou revisao, só com acao marcar_reuniao.',
  '- data_reuniao: ISO 8601 com o fuso de Brasília, por exemplo 2026-10-09T18:00:00-03:00. Só um horário que o cliente aceitou entre os HORÁRIOS LIVRES.',
  '- data_retomada: AAAA-MM, quando motivo_perda for Momento.',
  '- campos: só o que o cliente disse nesta conversa; o resto fica vazio.',
  '- nota: situação, problema, implicação, necessidade e objeções, com as palavras do cliente.',
  '- gancho_usado: o fato ou ângulo usado nesta mensagem, se houver.'
];
const cfg = {};
for (const i of $('Ler configuração').all()) { const r = i.json || {}; if (r.chave) cfg[r.chave] = { valor: String(r.valor ?? '').trim(), status: String(r.status || '').toUpperCase() }; }
const val = (k, d) => (cfg[k] && cfg[k].valor && cfg[k].status !== 'PENDENTE' && cfg[k].status !== 'OBSOLETO' ? cfg[k].valor : d);
const pegar = (n) => { try { return $(n).first().json; } catch (e) { return null; } };
const msg = $('Mensagem recebida').first().json;
const ident = $('Identificar negócio').first().json;
const dR = pegar('Buscar negócio'); const deal = dR && dR.success ? dR.data : null;
const pR = pegar('Buscar pessoa completa'); const pessoa = pR && pR.success ? pR.data : null;
const oR = pegar('Buscar empresa'); const org = oR && oR.success ? oR.data : null;
const limpar = (s) => String(s || '').replace(/<br\s*\/?>/gi, ' / ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();
const cf = (ent, chave) => { const id = val(chave, ''); if (!ent || !id) return ''; let x = (ent.custom_fields || {})[id]; if (x && typeof x === 'object') x = x.value !== undefined ? x.value : (x.label || ''); return x === null || x === undefined ? '' : String(x).trim(); };
const ehSim = (v, chaveSim) => /^(sim|true|1|yes)$/i.test(v) || (val(chaveSim, '') !== '' && v === val(chaveSim, ''));
const mapa = {};
for (const par of [['Em conversa', 'ETAPA_EM_CONVERSA'], ['Diagnóstico entregue', 'ETAPA_DIAGNOSTICO_ENTREGUE'], ['Reunião marcada', 'ETAPA_REUNIAO_MARCADA'], ['Proposta enviada', 'ETAPA_PROPOSTA_ENVIADA'], ['Em decisão', 'ETAPA_EM_DECISAO'], ['Contrato', 'ETAPA_CONTRATO']]) { const id = val(par[1], ''); if (id) mapa[id] = par[0]; }
let legado = {}; try { legado = JSON.parse(val('ETAPAS_LEGADO', '{}')); } catch (e) { legado = {}; }
const sid = deal ? String(deal.stage_id) : '';
const etapa = mapa[sid] || legado[sid] || 'Em conversa';
const pausada = ehSim(cf(deal, 'PD_DEAL_IA_PAUSADA'), 'PD_DEAL_IA_PAUSADA_SIM');
const naoContatar = ehSim(cf(pessoa, 'PD_PERSON_NAO_CONTATAR'), 'PD_PERSON_NAO_CONTATAR_SIM');
const linhas = [];
const add = (r, v) => { if (v) linhas.push(r + ': ' + v); };
add('Nome do contato', pessoa && pessoa.name);
add('Empresa', (org && org.name) || (deal && deal.title));
add('Site', org && org.website);
add('Cidade', cf(org, 'PD_ORG_CIDADE'));
add('Link da análise', cf(deal, 'PD_DEAL_DIAG_LINK'));
const defs = {};
for (const f of (((pegar('Campos do negócio') || {}).data) || [])) if (f && f.key) defs[f.key] = f;
if (deal) for (const k of Object.keys(deal.custom_fields || {})) {
  let x = deal.custom_fields[k]; const def = defs[k];
  if (!def || x === null || x === undefined || x === '') continue;
  if (x && typeof x === 'object') x = x.value !== undefined ? x.value : null;
  if (x === null || x === undefined || x === '') continue;
  if (Array.isArray(def.options) && def.options.length) { const rot = String(x).split(',').map((id) => (def.options.find((o) => String(o.id) === id.trim()) || {}).label).filter(Boolean); if (rot.length) x = rot.join(', '); }
  add(def.name, limpar(String(x)).slice(0, 400));
}
const agora = Date.now();
const ativs = (((pegar('Buscar atividades') || {}).data) || []);
const fmt = (d, h) => { const ms = Date.parse(d + 'T' + String(h).slice(0, 5) + ':00Z') - 3 * 3600000; const x = new Date(ms); const dias = ['domingo', 'segunda', 'terça', 'quarta', 'quinta', 'sexta', 'sábado']; return dias[x.getUTCDay()] + ', ' + x.toISOString().slice(8, 10) + '/' + x.toISOString().slice(5, 7) + ' às ' + x.toISOString().slice(11, 16); };
const reunioes = ativs.filter((a) => !a.done && a.type === 'meeting' && a.due_date && a.due_time && Date.parse(a.due_date + 'T' + String(a.due_time).slice(0, 5) + ':00Z') > agora).map((a) => '- ' + limpar(a.subject) + ': ' + fmt(a.due_date, a.due_time)).join('\n');
const notas = (((pegar('Buscar notas') || {}).data) || []).slice(0, 12).map((n) => '- ' + String(n.add_time || '').slice(0, 10) + ': ' + limpar(n.content).slice(0, 700)).join('\n');
const hist = $('Histórico da conversa').all().map((i) => i.json || {}).filter((r) => r.texto).sort((a, b) => Date.parse(a.criado_em) - Date.parse(b.criado_em)).slice(-30);
const conversa = hist.map((r) => (r.direcao === 'in' ? 'Cliente' : 'ATOM' + (r.tipo && r.tipo !== 'RESPOSTA' ? ' (' + r.tipo + ')' : '')) + ': ' + String(r.texto).slice(0, 600)).join('\n');
const ganchos = Array.from(new Set(hist.map((r) => r.gancho).filter(Boolean))).join('; ');
const loc = new Date(agora - 3 * 3600000);
const diasSemana = ['domingo', 'segunda', 'terça', 'quarta', 'quinta', 'sexta', 'sábado'];
const hoje = diasSemana[loc.getUTCDay()] + ', ' + loc.toISOString().slice(8, 10) + '/' + loc.toISOString().slice(5, 7) + '/' + loc.toISOString().slice(0, 4) + ', ' + loc.toISOString().slice(11, 16);
const horarios = val('AGENDA_HORARIOS_LIVRES', '');
const prompt = BASE.concat([
  '', 'ROTEIRO DA ETAPA ATUAL (' + etapa + '):', ROTEIROS[etapa] || ROTEIROS['Em conversa'],
  '', 'AGORA: ' + hoje + ' (horário de Brasília).',
  'HORÁRIOS LIVRES DO THIAGO: ' + (horarios || 'não informados. Não ofereça horários específicos: pergunte qual dia e período ficam melhores e use acao nenhuma; o Thiago confirma.'),
  '', 'DADOS DO CLIENTE:', linhas.join('\n') || '(poucos dados cadastrados)',
  'Reuniões agendadas: ' + (reunioes ? '\n' + reunioes : 'nenhuma'),
  '', 'NOTAS DO NEGÓCIO (mais recentes primeiro):', notas || '(sem notas)',
  '', 'CONVERSA ATÉ AGORA:', conversa || '(primeira mensagem)',
  '', 'GANCHOS JÁ USADOS COM ESTE CLIENTE (não repita):', ganchos || '(nenhum)',
  '', 'ÚLTIMA MENSAGEM DO CLIENTE: ' + String(msg.texto || ''),
  ''
]).concat(SAIDA).join('\n');
const owner = Number(val('PD_ALERTA_USER_ID', '0')) || undefined;
return [{ json: {
  numero: NUMERO, telefone: String(msg.telefone || '').replace(/\D/g, ''), texto: String(msg.texto || ''),
  deal_id: ident.deal_id, person_id: ident.person_id, etapa, pode_responder: !pausada && !naoContatar && !!ident.deal_id,
  motivo_sem_resposta: !ident.deal_id ? 'Negócio não encontrado nem criado' : (naoContatar ? 'Pessoa marcada como Não contatar' : (pausada ? 'IA pausada neste negócio' : '')),
  tarefa: { subject: 'Cliente escreveu no número ' + NUMERO + ' e a IA não respondeu', type: 'task', deal_id: ident.deal_id || undefined, owner_id: owner, due_date: loc.toISOString().slice(0, 10), note: 'Mensagem: ' + String(msg.texto || '').slice(0, 500) },
  prompt
} }];

const ctx = $('Montar prompt').first().json;
const t = String(($input.first().json || {}).text || '');
const a = t.indexOf('{'); const b = t.lastIndexOf('}');
let s = null;
try { s = JSON.parse(t.slice(a, b + 1)); } catch (e) { s = null; }
const acoes = ['nenhuma', 'mover_etapa', 'marcar_reuniao', 'registrar_aceite', 'reenviar_contrato', 'transferir_thiago', 'perdido', 'nao_contatar'];
if (!s || typeof s.mensagem !== 'string' || !acoes.includes(s.acao)) {
  s = { mensagem: '', acao: 'transferir_thiago', campos: {}, nota: 'A IA não gerou uma resposta válida para a mensagem: "' + ctx.texto.slice(0, 300) + '". Responda manualmente.', gancho_usado: '' };
}
if (s.acao === 'registrar_aceite' || s.acao === 'reenviar_contrato') { s.nota = String(s.nota || '') + ' (A IA passiva não registra aceite nem contrato: transferido ao Thiago.)'; s.acao = 'transferir_thiago'; }
s.mensagem = String(s.mensagem || '').trim();
return [{ json: { saida: s, deal_id: ctx.deal_id, person_id: ctx.person_id, numero: ctx.numero, telefone: ctx.telefone, mensagem: s.mensagem, gancho: String(s.gancho_usado || '') } }];
